	bit 7, a                    ; 4308: CB 7F  bit 7: music
	jr nz, .playMusic           ; 430A: 20 5E
	bit 6, a                    ; 430C: CB 77  bit 6: high priority, always plays
	jr nz, .startSfx            ; 430E: 20 04
	ldh a, [hSfxHighPri]        ; 4310: F0 95  a high-priority SFX is running
	or a                        ; 4312: B7
	ret nz                      ; 4313: C0
.startSfx:
	xor a                       ; 4314: AF
	ldh [hSfxTimer], a          ; 4315: E0 8D
	ldh [hSfxTranspose], a      ; 4317: E0 8C
	ldh [hSfxWaitAdd], a        ; 4319: E0 90
	ldh a, [hSfxOwnCh1]         ; 431B: F0 91
	or a                        ; 431D: B7
	jp z, .freeCh2              ; 431E: CA 26 43
	xor a                       ; 4321: AF
	ldh [rNR12], a              ; 4322: E0 12
	ldh [hSfxOwnCh1], a         ; 4324: E0 91
.freeCh2:
	ldh a, [hSfxOwnCh2]         ; 4326: F0 92
	or a                        ; 4328: B7
	jp z, .freeCh3              ; 4329: CA 31 43
	xor a                       ; 432C: AF
	ldh [rNR22], a              ; 432D: E0 17
	ldh [hSfxOwnCh2], a         ; 432F: E0 92
.freeCh3:
	ldh a, [hSfxOwnCh3]         ; 4331: F0 93
	or a                        ; 4333: B7
	jp z, .freeCh4              ; 4334: CA 3C 43
	xor a                       ; 4337: AF
	ldh [rNR32], a              ; 4338: E0 1C
	ldh [hSfxOwnCh3], a         ; 433A: E0 93
.freeCh4:
	ldh a, [hSfxOwnCh4]         ; 433C: F0 94
	or a                        ; 433E: B7
	jp z, .setSfx               ; 433F: CA 47 43
	xor a                       ; 4342: AF
	ldh [rNR42], a              ; 4343: E0 21
	ldh [hSfxOwnCh4], a         ; 4345: E0 94
.setSfx:
	ld a, b                     ; 4347: 78
	and $40                     ; 4348: E6 40
	ldh [hSfxHighPri], a        ; 434A: E0 95
	ld a, b                     ; 434C: 78
	and $3F                     ; 434D: E6 3F
	add a, a                    ; 434F: 87
	ld e, a                     ; 4350: 5F
	ld d, $00                   ; 4351: 16 00
	ld hl, SoundTable           ; 4353: 21 E0 49
	add hl, de                  ; 4356: 19
	ld a, [hli]                 ; 4357: 2A
	ldh [hSfxPtr], a            ; 4358: E0 8E
	ld a, [hli]                 ; 435A: 2A
	ldh [hSfxPtr + 1], a        ; 435B: E0 8F
	ld a, $77                   ; 435D: 3E 77
	ldh [rNR50], a              ; 435F: E0 24
	ld a, $FF                   ; 4361: 3E FF
	ldh [rNR51], a              ; 4363: E0 25
	ld a, $01                   ; 4365: 3E 01
	ldh [hSfxTimer], a          ; 4367: E0 8D
	ret                         ; 4369: C9
.playMusic:
	call SndSilence             ; 436A: CD B8 43
	ldh [hMusTimer], a          ; 436D: E0 9B
	ldh [hMusUnused13], a       ; 436F: E0 9D
	ldh [hMusPaused], a         ; 4371: E0 9E
	dec a                       ; 4373: 3D
	ldh [hMusUnused12], a       ; 4374: E0 9C
	ldh [hMusWave], a           ; 4376: E0 9F
	ld a, b                     ; 4378: 78

MusicStart:
	and $3F                     ; 4379: E6 3F
	add a, a                    ; 437B: 87
	ld e, a                     ; 437C: 5F
	ld d, $00                   ; 437D: 16 00
	ld hl, SoundTable           ; 437F: 21 E0 49
	add hl, de                  ; 4382: 19
	ld a, [hli]                 ; 4383: 2A
	ld h, [hl]                  ; 4384: 66
	ld l, a                     ; 4385: 6F
	ld a, [hli]                 ; 4386: 2A
	ldh [hMusNumDefs], a        ; 4387: E0 96
	ld e, a                     ; 4389: 5F
	ld d, $00                   ; 438A: 16 00
	ld a, l                     ; 438C: 7D
	ldh [hMusDefs], a           ; 438D: E0 97
	ld a, h                     ; 438F: 7C
	ldh [hMusDefs + 1], a       ; 4390: E0 98
	add hl, de                  ; 4392: 19
	add hl, de                  ; 4393: 19
	ld a, l                     ; 4394: 7D
	ldh [hMusPtr], a            ; 4395: E0 99
	ld a, h                     ; 4397: 7C
	ldh [hMusPtr + 1], a        ; 4398: E0 9A
	ld a, $77                   ; 439A: 3E 77
	ldh [rNR50], a              ; 439C: E0 24
	ld a, $FF                   ; 439E: 3E FF
	ldh [rNR51], a              ; 43A0: E0 25
	ld a, $01                   ; 43A2: 3E 01
	ldh [hMusTimer], a          ; 43A4: E0 9B
	ret                         ; 43A6: C9

SndRandom:
	push hl                     ; 43A7: E5
	ld hl, hSndRandom           ; 43A8: 21 8A FF
	ld a, [hl]                  ; 43AB: 7E
	rla                         ; 43AC: 17
	xor [hl]                    ; 43AD: AE
	and $40                     ; 43AE: E6 40
	jr z, .shift                ; 43B0: 28 01
	ccf                         ; 43B2: 3F
.shift:
	ld a, [hl]                  ; 43B3: 7E
	rla                         ; 43B4: 17
	ld [hl], a                  ; 43B5: 77
	pop hl                      ; 43B6: E1
	ret                         ; 43B7: C9

SndSilence:
	xor a                       ; 43B8: AF
	ldh [rNR12], a              ; 43B9: E0 12
	ldh [rNR22], a              ; 43BB: E0 17
	ldh [rNR32], a              ; 43BD: E0 1C
	ldh [rNR42], a              ; 43BF: E0 21
	ldh [rNR14], a              ; 43C1: E0 14
	ldh [rNR24], a              ; 43C3: E0 19
	ldh [rNR34], a              ; 43C5: E0 1E
	ldh [rNR44], a              ; 43C7: E0 23
	ldh [hVoice1], a            ; 43C9: E0 A0
	ldh [hVoice2], a            ; 43CB: E0 A6
	ldh [hVoice3], a            ; 43CD: E0 AC
	ldh [hVoice4], a            ; 43CF: E0 B2
	ret                         ; 43D1: C9

